/* CastDepMapper.insertUserDepList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_DEP ( SMLT_ID, TMNL_ID, DEP_NUM, OPER_YN, SCRTY_CNTRL_CNT, NRML_CNT, SMART_PASS_CNT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{dep.depNum}, #{dep.oprYn}, #{dep.scCnt}, #{dep.normalCnt}, #{dep.smartPassCnt}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL

/* CastDepMapper.insertUserDepOperHrList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_DEP_OPER_HR ( SMLT_ID, TMNL_ID, DEP_NUM, OPER_HR_SN, OPER_BGNG_HR, OPER_END_HR, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{dep.depNum}, #{oprTimeIdx} + 1, #{oprTime.bgnHour}, #{oprTime.endHour}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL

/* CastDepMapper.insertUserScPlanList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_SC_PLAN ( SMLT_ID, TMNL_ID, DEP_NUM, PLAN_SN, OPER_BGNG_HR, OPER_END_HR, SCRTY_CNTRL_CNT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{dep.depNum}, #{planIdx} + 1, #{plan.bgnHour}, #{plan.endHour}, #{plan.scCnt}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL
